<script setup lang="ts">
import { CircleCheck, CircleX, Clock3, ArrowLeft } from 'lucide-vue-next'
import { formatPrice } from '../shared'
const route = useRoute()
const code = typeof route.query.code === 'string' ? route.query.code : ''
const { data: order } = code ? await useFetch<{code:string;total:number;payment_status:string;ref_id:string|null;items:unknown[]}>('/api/orders/' + code) : { data: ref(null) }
const { clear } = useCart()
onMounted(() => { if (order.value?.payment_status === 'paid') clear() })
useSeoMeta({ title: 'نتیجه‌ی پرداخت | پیله پاتری' })
</script>
<template><div class="container result-page"><div class="result-box" v-if="order"><CircleCheck v-if="order.payment_status==='paid'" :size="50" :stroke-width="1" class="result-icon ok"/><CircleX v-else-if="['failed','expired','cancelled'].includes(order.payment_status)" :size="50" :stroke-width="1" class="result-icon bad"/><Clock3 v-else :size="50" :stroke-width="1" class="result-icon waiting"/><h1>{{ order.payment_status==='paid' ? 'پرداخت شما موفق بود' : order.payment_status==='pending' ? 'پرداخت در حال بررسی است' : 'پرداخت انجام نشد' }}</h1><p>{{ order.payment_status==='paid' ? 'از همراهی شما سپاسگزاریم. سفارش شما ثبت شد.' : order.payment_status==='pending' ? 'در صورت کسر وجه، لطفاً برای بررسی با پشتیبانی در تماس باشید.' : 'در صورت کسر وجه، مبلغ طبق روال بانکی بازگردانده می‌شود.' }}</p><div class="result-details"><div><span>شماره سفارش</span><strong dir="ltr">{{ order.code }}</strong></div><div><span>مبلغ سفارش</span><strong>{{ formatPrice(order.total) }} تومان</strong></div><div v-if="order.ref_id"><span>کد پیگیری زرین‌پال</span><strong dir="ltr">{{ order.ref_id }}</strong></div></div><NuxtLink to="/products" class="btn">بازگشت به فروشگاه <ArrowLeft :size="16"/></NuxtLink></div><div v-else class="empty-state"><h1>سفارشی پیدا نشد</h1><NuxtLink to="/products" class="btn">بازگشت به فروشگاه</NuxtLink></div></div></template>
<style scoped>.result-page{padding:100px 0 130px}.result-box{background:#e9ebea;max-width:620px;margin:auto;text-align:center;padding:62px 60px}.result-icon{margin:0 auto 20px}.ok{color:#6a7b56}.bad{color:#af6956}.waiting{color:#ad8a51}.result-box h1{font-size:27px;font-weight:500;margin:0}.result-box p{font-size:13px;color:var(--muted);line-height:2}.result-details{border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:30px 0;padding:15px 0}.result-details div{display:flex;justify-content:space-between;padding:8px 0;font-size:12px}.result-details span{color:var(--muted)}.result-details strong{font-weight:500}.result-box .btn{margin-top:5px}@media(max-width:650px){.result-page{padding:55px 0}.result-box{padding:40px 22px}}</style>
